#!/bin/bash
# Prints the three IP addresses that appear most often in access.log,
# one per line, most frequent first. Ties are broken by first appearance
# in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '{
    ip = $1
    if (!(ip in seen)) {
        seen[ip] = 1
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        print count[ip], i, ip
    }
}' access.log | sort -k1,1nr -k2,2n | head -n 3 | awk '{print $3}'
